versions.variantCss:
.wemd-quote-card[data-variant="bytedance-quote-accent"] {
  background: var(--wemd-bg-card);
  border-radius: var(--wemd-border-radius);
  padding: 24px 28px;
  margin: 16px 0;
  border-left: 4px solid var(--wemd-primary);
  box-shadow: var(--wemd-shadow);
}
.wemd-quote-card[data-variant="bytedance-quote-accent"] .wemd-component-body {
  padding: 0;
}
.wemd-quote-card[data-variant="bytedance-quote-accent"] .wemd-component-body .wemd-child-1 {
  color: var(--wemd-text-strong);
  font-size: 17px;
  font-style: italic;
  line-height: 1.75;
  margin: 0 0 8px 0;
}
.wemd-quote-card[data-variant="bytedance-quote-accent"] .wemd-component-body .wemd-child-2 {
  color: var(--wemd-text-soft);
  font-size: 13px;
  margin: 0;
}
